46	// unify unifies calling all of funcs into a single function call. All errors
47	// returned from calls to funcs will be unify into a single error return
48	// value.
49	func unify(funcs []func(context.Context) error) func(context.Context) error {
50		return func(ctx context.Context) error {
51			var err error
52			for _, f := range funcs {
53				if e := f(ctx); e != nil {
54					err = errors.Join(err, e)
55				}
56			}
57			return err
58		}
59	}
60	
61	// unifyShutdown unifies calling all of funcs once for a shutdown. If called
62	// more than once, an ErrReaderShutdown error is returned.
63	func unifyShutdown(funcs []func(context.Context) error) func(context.Context) error {
64		f := unify(funcs)
65		var once sync.Once
66		return func(ctx context.Context) error {
67			err := ErrReaderShutdown
68			once.Do(func() { err = f(ctx) })
69			return err
70		}
71	}
