// WithDefaultAttributes returns a [metric.InstrumentOption] that specifies the
// attribute keys that are allowed by default for a metric instrument.
//
// Only the attributes whose keys are included in keys will be present in the
// data points recorded by the instrument. Any other attribute recorded with a
// measurement is treated as opt-in and filtered out by default.
//
// Passing no keys results in all attributes being filtered out, producing data
// points with an empty attribute set.
//
// SDK users can re-enable the filtered attributes by registering a View with an
// [go.opentelemetry.io/otel/sdk/metric.Stream] AttributeFilter that matches the
// instrument. In that case the View's attribute configuration takes precedence
// over the default attributes.
func WithDefaultAttributes(keys ...attribute.Key) metric.InstrumentOption {
	return defaultAttributesOption{keys: keys}
}

type defaultAttributesOption struct {
	// InstrumentOption is embedded so defaultAttributesOption implements the
	// metric.InstrumentOption interface. Its methods are never called because
	// the option is skipped by the API via the Experimental marker below.
	metric.InstrumentOption

	keys []attribute.Key
}

// Experimental marks the option as experimental. It prevents the standard API
// from panicking when the option is used, by signaling that the option should
// be skipped when a configuration is applied.
func (defaultAttributesOption) Experimental() {}

// AllowedKeys returns the attribute keys that are allowed by default.
func (o defaultAttributesOption) AllowedKeys() []attribute.Key {
	return o.keys
}
